fn rsqrt(v: f32) f32 {
  // (trm 256) two Newton steps: relative error 4.6e-6 (the rms scales; 1/l = rsqrt^2, 9.2e-6)
  var y = @bitcast(f32, @as(u32, 0x5f3759df) - (@bitcast(u32, v) >> 1));
  const h = 0.5 * v;
  y = y * (1.5 - h * y * y);
  y = y * (1.5 - h * y * y);
  return y;
}
